const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : input;
const raw = body.reflection ?? body.emotion ?? '';
const emotion = typeof raw === 'string' ? raw.trim() : '';
const valid = emotion.length >= 1 && emotion.length <= 500;

return [{
  json: {
    valid,
    emotion,
    website: 'https://www.imagehealthy.com/',
    error: valid
      ? null
      : 'Provide reflection or emotion as a string between 1 and 500 characters.',
  },
}];

const api = $input.first().json;
const data = api.data ?? {};
const goals = Array.isArray(data.recommendedGoals) ? data.recommendedGoals : [];
const stateLabels = {
  overwhelmed: 'overwhelmed',
  sad: 'sad or low',
  lonely: 'lonely',
  angry: 'angry or frustrated',
  tense: 'tense or anxious',
  exhausted: 'tired or depleted',
  unclear: 'in need of a steadier direction',
};
const goalLabels = {
  space: 'more breathing room',
  comfort: 'comfort',
  grounding: 'grounding',
  boundary: 'clearer boundaries',
  hope: 'a sense of hope',
  restore: 'restoration',
};
const currentState = data.currentState ?? 'unclear';
const readableGoals = goals.map((goal) => goalLabels[goal] ?? goal);

return [{
  json: {
    ok: true,
    currentState,
    recommendedGoals: goals,
    message: `The reflection sounds ${stateLabels[currentState] ?? currentState}. Consider ${readableGoals.join(' or ')} as the next visual direction.`,
    website: 'https://www.imagehealthy.com/',
    disclaimer: 'Creative reflection only; not medical, diagnostic, crisis, or mental health care.',
  },
}];

const api = $input.first().json;

return [{
  json: {
    ok: false,
    error: api.message ?? api.error?.message ?? 'ImageHealAI could not return a calming direction.',
    errorCode: api.data?.errorCode ?? api.errorCode ?? 'UPSTREAM_ERROR',
    website: 'https://www.imagehealthy.com/',
  },
}];

const input = $input.first().json;

return [{
  json: {
    ok: false,
    error: input.error,
    errorCode: 'INVALID_INPUT',
    expectedBody: {
      reflection: 'A short, de-identified description between 1 and 500 characters.',
    },
    website: input.website,
  },
}];
